import { lazy } from 'react';
import { CalendarRange as IcCalendarRange, ClipboardList as IcClipboardList, Goal as IcGoal, Target as IcTarget, Users as IcUsers } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Cycles & Goals — hub page for the Performance menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 4 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'PerformanceManage'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const TeamPerformance = lazy(() => import('./TeamPerformance'));
const ReviewCycleManager = lazy(() => import('./ReviewCycleManager'));
const KRAManagement = lazy(() => import('./KRAManagement'));
const OKRManagement = lazy(() => import('./OKRManagement'));

export const TABS = [
  { id: 'team', label: 'Team Performance', icon: IcUsers, page: 'TeamPerformance', Component: TeamPerformance },
  { id: 'cycles', label: 'Review Cycles', icon: IcCalendarRange, page: 'ReviewCycleManager', Component: ReviewCycleManager },
  { id: 'kra', label: 'KRA Management', icon: IcTarget, page: 'KRAManagement', Component: KRAManagement },
  { id: 'okr', label: 'OKR Management', icon: IcGoal, page: 'OKRManagement', Component: OKRManagement },
];

export default function PerformanceManage({ setPage }) {
  return (
    <TabHub
      icon={IcClipboardList}
      eyebrow="Performance"
      title="Cycles & Goals"
      subtitle="Team reviews, review cycles, KRAs and OKRs"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
